import test from "node:test";
import assert from "node:assert/strict";
import {apply, planner} from "./replay.mjs";

const catalog = {default: 5, studios: new Map([["orchid", 8], ["iris", 3]])};
const book = (id, units, tenant = "orchid", day = "2025-04-02", service = "studio") =>
  ({action: "book", service, id, tenant, day, units});
const renew = (previous, id, day, units) =>
  ({action: "renew", service: "studio", previous, id, day, units});

test("Studio quotas are per tenant/day, including lower allocations and fallback", () => {
  const dispatch = planner(catalog);
  assert.deepEqual(dispatch(book("morning", 3)), {status: "booked", id: "morning", remaining: 5});
  assert.deepEqual(dispatch(book("evening", 5)), {status: "booked", id: "evening", remaining: 0});
  assert.deepEqual(dispatch(book("extra", 1)), {status: "full", id: "extra", remaining: 0});
  assert.equal(dispatch(book("tomorrow", 8, "orchid", "2025-04-03")).status, "booked");
  assert.deepEqual(dispatch(book("iris-large", 4, "iris")), {status: "full", id: "iris-large", remaining: 3});
  assert.equal(dispatch(book("iris-small", 3, "iris")).remaining, 0);
  assert.equal(dispatch(book("unlisted-large", 6, "rose")).status, "full");
  assert.equal(dispatch(book("unlisted", 5, "rose")).remaining, 0);
  assert.deepEqual(dispatch({action: "usage", service: "studio", tenant: "orchid", day: "2025-04-02"}), {units: 8});
  assert.equal(dispatch(book("archive-large", 6, "orchid", "2025-04-02", "archive")).status, "full");
  assert.equal(dispatch(book("archive", 5, "orchid", "2025-04-02", "archive")).remaining, 0);
});

test("replays, conflicts, cancellations and imported usage retain journal semantics", () => {
  const dispatch = planner(catalog);
  const request = book("sample", 7);
  assert.equal(dispatch(request).status, "booked");
  assert.equal(dispatch(request).status, "replay");
  assert.equal(dispatch({...request, units: 8}).status, "conflict");
  assert.equal(dispatch({...request, tenant: "rose"}).status, "conflict");
  assert.equal(dispatch({...request, day: "2025-04-03"}).status, "conflict");
  assert.equal(dispatch({service: "studio", action: "cancel", id: request.id}).status, "cancelled");
  assert.equal(dispatch(request).status, "cancelled");
  assert.equal(dispatch({service: "studio", action: "cancel", id: request.id}).status, "replay");
  const imported = book("backfill", 10);
  assert.equal(dispatch({...imported, action: "import"}).status, "imported");
  assert.equal(dispatch(imported).status, "replay");
  assert.deepEqual(dispatch(book("blocked", 1)), {status: "full", id: "blocked", remaining: 0});
  dispatch({service: "studio", action: "cancel", id: imported.id});
  assert.equal(dispatch(book("replacement", 8)).status, "booked");
  const summary = dispatch({service: "studio", action: "summary"});
  assert.deepEqual(summary.occupied.map(row => row.id), ["replacement"]);
  assert.equal(summary.events.filter(event => event.type === "booked").length, 3);
  assert.deepEqual(apply(dispatch, book("invalid", 0)), {status: "invalid", field: "units"});
});

test("renewals use the previous tenant and Studio admission, not the platform default", () => {
  const dispatch = planner(catalog);
  dispatch(book("previous", 7));
  const operation = renew("previous", "next", "2025-05-02");
  assert.deepEqual(dispatch({...operation, tenant: "rose"}), {status: "booked", id: "next", remaining: 1});
  assert.equal(dispatch(operation).status, "replay");
  assert.equal(dispatch({...operation, units: 8}).status, "conflict");
  assert.equal(dispatch(renew("previous", "too-large", "2025-06-02", 9)).status, "full");
  dispatch(book("may-other", 1, "orchid", "2025-05-02"));
  assert.deepEqual(dispatch(renew("previous", "may-extra", "2025-05-02", 1)),
    {status: "full", id: "may-extra", remaining: 0});
  dispatch({service: "studio", action: "cancel", id: "next"});
  assert.equal(dispatch(operation).status, "cancelled");
  assert.equal(dispatch(renew("absent", "missing", "2025-05-02")).status, "missing");
  dispatch({service: "studio", action: "cancel", id: "previous"});
  assert.equal(dispatch(operation).status, "missing");
  dispatch(book("rose-old", 5, "rose"));
  assert.equal(dispatch(renew("rose-old", "rose-next", "2025-05-02", 6)).status, "full");
  assert.equal(dispatch(renew("rose-old", "rose-next", "2025-05-02")).status, "booked");
  dispatch(book("archive-old", 5, "orchid", "2025-04-02", "archive"));
  assert.equal(dispatch({...renew("archive-old", "archive-next", "2025-05-02", 6), service: "archive"}).status, "full");
});
